<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#0d1117;--bg-card:#161b22;--bg-card-hover:#1c2129;
  --border:#30363d;--border-light:#21262d;
  --text:#e6edf3;--text-secondary:#8b949e;--text-muted:#6e7681;
  --accent:#00d4aa;--accent-hover:#00f0c0;--accent-dim:rgba(0,212,170,0.12);
  --blue:#475f91;--blue-light:#5876a8;
  --radius:8px;--radius-lg:12px;
  --font-body:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
  --font-mono:ui-monospace,SFMono-Regular,'SF Mono',Menlo,Consolas,'Liberation Mono',monospace;
  --sidebar-width:260px;
}
html{scroll-behavior:smooth}
body{font-family:var(--font-body);background:var(--bg);color:var(--text);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:var(--accent);text-decoration:none;transition:color .2s}
a:hover{color:var(--accent-hover)}
::selection{background:var(--accent);color:var(--bg)}

/* Top Nav */
.topnav{position:sticky;top:0;z-index:100;background:rgba(13,17,23,0.85);backdrop-filter:blur(12px);border-bottom:1px solid var(--border-light);padding:0 24px;height:60px;display:flex;align-items:center;justify-content:space-between}
.topnav-brand{font-weight:700;font-size:18px;color:var(--text);display:flex;align-items:center;gap:8px;white-space:nowrap}
.topnav-brand svg{width:24px;height:24px;fill:var(--accent)}
.topnav-links{display:flex;align-items:center;gap:28px;list-style:none}
.topnav-links a{color:var(--text-secondary);font-size:14px;font-weight:500;transition:color .2s}
.topnav-links a:hover{color:var(--text)}
.topnav-right{display:flex;align-items:center;gap:16px}
.topnav-search{display:flex;align-items:center;gap:6px;background:var(--bg-card);border:1px solid var(--border);border-radius:6px;padding:6px 12px;font-size:13px;color:var(--text-secondary);cursor:pointer;transition:border-color .2s}
.topnav-search:hover{border-color:var(--accent)}
.topnav-search svg{width:14px;height:14px;stroke:var(--text-secondary)}
.topnav-search kbd{font-family:var(--font-mono);font-size:11px;background:var(--border-light);border-radius:3px;padding:1px 5px;color:var(--text-muted)}
.btn-login{font-size:13px;font-weight:500;color:var(--text-secondary);background:none;border:1px solid var(--border);border-radius:6px;padding:6px 14px;cursor:pointer;transition:all .2s}
.btn-login:hover{border-color:var(--text-secondary);color:var(--text)}

/* Hero */
.hero{padding:80px 24px 60px;max-width:960px;margin:0 auto;text-align:center}
.hero-badge{display:inline-flex;align-items:center;gap:6px;background:var(--accent-dim);border:1px solid rgba(0,212,170,0.25);border-radius:20px;padding:6px 16px;font-size:13px;color:var(--accent);font-weight:500;margin-bottom:24px}
.hero h1{font-size:clamp(36px,5vw,56px);font-weight:800;line-height:1.1;letter-spacing:-0.02em;margin-bottom:20px}
.hero h1 span{color:var(--accent)}
.hero p{font-size:18px;color:var(--text-secondary);max-width:720px;margin:0 auto 32px;line-height:1.7}
.hero-ctas{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.btn-primary{display:inline-flex;align-items:center;gap:6px;background:var(--accent);color:var(--bg);font-weight:600;font-size:14px;padding:10px 20px;border-radius:6px;border:none;cursor:pointer;transition:all .2s;text-decoration:none}
.btn-primary:hover{background:var(--accent-hover);color:var(--bg);transform:translateY(-1px)}
.btn-primary svg{width:16px;height:16px;stroke:var(--bg);fill:none;stroke-width:2}
.btn-secondary{display:inline-flex;align-items:center;gap:6px;background:transparent;color:var(--text);font-weight:500;font-size:14px;padding:10px 20px;border-radius:6px;border:1px solid var(--border);cursor:pointer;transition:all .2s;text-decoration:none}
.btn-secondary:hover{border-color:var(--text-secondary);color:var(--text)}

/* Product Cards */
.section{padding:60px 24px;max-width:1200px;margin:0 auto}
.section-title{font-size:28px;font-weight:700;margin-bottom:12px;letter-spacing:-0.01em}
.section-subtitle{font-size:16px;color:var(--text-secondary);margin-bottom:40px;max-width:600px}
.product-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}
.product-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:32px;transition:all .3s;position:relative;overflow:hidden}
.product-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--accent);opacity:0;transition:opacity .3s}
.product-card:hover{border-color:var(--accent);background:var(--bg-card-hover);transform:translateY(-2px)}
.product-card:hover::before{opacity:1}
.product-card-icon{width:48px;height:48px;border-radius:10px;display:flex;align-items:center;justify-content:center;margin-bottom:20px;font-size:24px}
.product-card-icon.apps{background:rgba(0,212,170,0.12);color:var(--accent)}
.product-card-icon.storefronts{background:rgba(136,98,255,0.12);color:#8862ff}
.product-card-icon.agents{background:rgba(255,152,0,0.12);color:#ff9800}
.product-card h3{font-size:20px;font-weight:600;margin-bottom:8px}
.product-card p{font-size:14px;color:var(--text-secondary);line-height:1.6;margin-bottom:20px}
.product-card a{font-size:14px;font-weight:500;display:inline-flex;align-items:center;gap:4px}
.product-card a::after{content:'→';transition:transform .2s}
.product-card:hover a::after{transform:translateX(3px)}

/* CLI Section */
.cli-section{background:var(--bg-card);border:1px solid var(--border-light);border-radius:var(--radius-lg);overflow:hidden;max-width:960px;margin:0 auto}
.cli-header{padding:40px 40px 0;text-align:center}
.cli-header h2{font-size:28px;font-weight:700;margin-bottom:8px;letter-spacing:-0.01em}
.cli-header p{font-size:15px;color:var(--text-secondary);max-width:600px;margin:0 auto 32px;line-height:1.6}

/* Tabs */
.tab-bar{display:flex;border-bottom:1px solid var(--border);padding:0 40px}
.tab-btn{padding:12px 20px;font-size:14px;font-weight:500;color:var(--text-muted);background:none;border:none;border-bottom:2px solid transparent;cursor:pointer;transition:all .2s;font-family:var(--font-mono)}
.tab-btn:hover{color:var(--text-secondary)}
.tab-btn.active{color:var(--accent);border-bottom-color:var(--accent)}

/* Code block */
.code-block{background:#010409;border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:20px 40px;position:relative}
.code-block code{font-family:var(--font-mono);font-size:14px;color:var(--text);display:block;white-space:pre;line-height:1.8}
.code-block .prompt{color:var(--accent);user-select:none}
.code-block .comment{color:var(--text-muted)}
.copy-btn{position:absolute;top:12px;right:16px;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;padding:4px 8px;font-size:12px;color:var(--text-secondary);cursor:pointer;transition:all .2s;font-family:var(--font-mono)}
.copy-btn:hover{border-color:var(--accent);color:var(--accent)}

/* Accordion */
.accordion{border-top:1px solid var(--border)}
.accordion-item{border-bottom:1px solid var(--border)}
.accordion-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;padding:20px 40px;background:none;border:none;color:var(--text);font-size:16px;font-weight:500;cursor:pointer;text-align:left;transition:background .2s;font-family:var(--font-body)}
.accordion-trigger:hover{background:rgba(255,255,255,0.02)}
.accordion-trigger svg{width:20px;height:20px;stroke:var(--text-secondary);fill:none;stroke-width:2;transition:transform .3s}
.accordion-item.open .accordion-trigger svg{transform:rotate(180deg)}
.accordion-trigger .acc-label{display:flex;align-items:center;gap:10px}
.accordion-trigger .acc-num{font-size:12px;color:var(--text-muted);font-family:var(--font-mono);background:var(--border-light);border-radius:4px;padding:2px 8px}
.accordion-content{max-height:0;overflow:hidden;transition:max-height .35s ease}
.accordion-item.open .accordion-content{max-height:500px}
.accordion-inner{padding:0 40px 24px}
.accordion-inner ol{padding-left:0;list-style:none;counter-reset:steps}
.accordion-inner li{counter-increment:steps;font-size:14px;color:var(--text-secondary);padding:8px 0 8px 32px;position:relative;line-height:1.6}
.accordion-inner li::before{content:counter(steps);position:absolute;left:0;top:8px;width:20px;height:20px;background:var(--accent-dim);color:var(--accent);border-radius:50%;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center}
.accordion-inner .init-cmd{margin-top:12px;background:#010409;border:1px solid var(--border);border-radius:6px;padding:14px 18px;font-family:var(--font-mono);font-size:13px;color:var(--text)}

/* Launch CTA */
.launch-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.launch-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:32px;display:flex;flex-direction:column;gap:12px}
.launch-card h3{font-size:20px;font-weight:600}
.launch-card p{font-size:14px;color:var(--text-secondary);line-height:1.6;flex:1}

/* Community */
.community-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
.community-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:24px;transition:all .2s;text-decoration:none;display:block}
.community-card:hover{border-color:var(--accent);transform:translateY(-1px)}
.community-card h4{font-size:15px;font-weight:500;color:var(--text);margin-bottom:4px;display:flex;align-items:center;gap:6px}
.community-card p{font-size:13px;color:var(--text-secondary);line-height:1.5}

/* Footer */
.site-footer{border-top:1px solid var(--border-light);padding:48px 24px 32px;margin-top:60px}
.footer-inner{max-width:1200px;margin:0 auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:40px}
.footer-col h5{font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;color:var(--text-muted);margin-bottom:16px}
.footer-col ul{list-style:none}
.footer-col li{margin-bottom:8px}
.footer-col a{font-size:14px;color:var(--text-secondary)}
.footer-col a:hover{color:var(--text)}
.footer-bottom{max-width:1200px;margin:32px auto 0;padding-top:24px;border-top:1px solid var(--border-light);display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--text-muted)}

/* Responsive */
@media(max-width:768px){
  .topnav-links{display:none}
  .topnav-search kbd{display:none}
  .hero{padding:48px 20px 40px}
  .hero h1{font-size:32px}
  .hero p{font-size:16px}
  .section{padding:40px 20px}
  .cli-header{padding:24px 20px 0}
  .tab-bar{padding:0 20px}
  .code-block{padding:16px 20px}
  .accordion-trigger{padding:16px 20px}
  .accordion-inner{padding:0 20px 20px}
  .launch-grid{grid-template-columns:1fr}
  .product-cards{grid-template-columns:1fr}
  .footer-inner{grid-template-columns:1fr 1fr}
}

/* Mobile nav toggle */
.mobile-toggle{display:none;background:none;border:none;color:var(--text);cursor:pointer;padding:4px}
@media(max-width:768px){.mobile-toggle{display:flex}}
.mobile-nav{display:none;position:fixed;top:60px;left:0;right:0;bottom:0;background:var(--bg);z-index:99;padding:24px;border-top:1px solid var(--border)}
.mobile-nav.open{display:block}
.mobile-nav a{display:block;padding:12px 0;font-size:16px;color:var(--text-secondary);border-bottom:1px solid var(--border-light)}
.mobile-nav a:hover{color:var(--text)}

/* Tab content */
.tab-content{display:none}
.tab-content.active{display:block}
</style>
</head>
<body>

<!-- Top Navigation -->
<nav class="topnav">
  <div class="topnav-brand">
