</section>

<!-- CLI Setup -->
<section class="section">
  <div class="cli-section">
    <div class="cli-header">
      <h2>Accelerate development with CommerceForge CLI 3.0</h2>
      <p>Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need, including the CLI itself, so you can dive straight into development.</p>
    </div>

    <!-- Package Manager Tabs -->
    <div class="tab-bar" role="tablist">
      <button class="tab-btn active" role="tab" data-tab="npm" onclick="switchTab('npm')">npm</button>
      <button class="tab-btn" role="tab" data-tab="yarn" onclick="switchTab('yarn')">yarn</button>
      <button class="tab-btn" role="tab" data-tab="pnpm" onclick="switchTab('pnpm')">pnpm</button>
    </div>

    <!-- Code Block -->
    <div class="code-block">
      <button class="copy-btn" onclick="copyInstall(this)">Copy</button>
      <div class="tab-content active" id="tab-npm">
        <code><span class="prompt">$</span> <span class="comment"># Install CommerceForge CLI globally</span>
<span class="prompt">$</span> npm i -g @commerceforge/cli@latest</code>
      </div>
      <div class="tab-content" id="tab-yarn">
        <code><span class="prompt">$</span> <span class="comment"># Install CommerceForge CLI globally</span>
<span class="prompt">$</span> yarn global add @commerceforge/cli@latest</code>
      </div>
      <div class="tab-content" id="tab-pnpm">
        <code><span class="prompt">$</span> <span class="comment"># Install CommerceForge CLI globally</span>
<span class="prompt">$</span> pnpm add -g @commerceforge/cli@latest</code>
      </div>
    </div>

    <!-- Accordion -->
    <div class="accordion">
      <div class="accordion-item open" data-accordion="apps">
        <button class="accordion-trigger" onclick="toggleAccordion('apps')" aria-expanded="true">
          <span class="acc-label"><span class="acc-num">1</span> Apps</span>
          <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-content">
          <div class="accordion-inner">
            <ol>
              <li>Install CommerceForge CLI globally using the command above.</li>
              <li>Navigate to the directory where you want to create your app.</li>
              <li>Run the command below to create a new app. Your app will be added as a new subdirectory.</li>
            </ol>
            <div class="init-cmd"><span class="prompt" style="color:var(--accent)">$</span> commerceforge app init</div>
          </div>
        </div>
      </div>
      <div class="accordion-item" data-accordion="themes">
        <button class="accordion-trigger" onclick="toggleAccordion('themes')" aria-expanded="false">
          <span class="acc-label"><span class="acc-num">2</span> Themes</span>
          <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-content">
          <div class="accordion-inner">
            <ol>
              <li>Install CommerceForge CLI globally using the command above.</li>
              <li>Navigate to the directory where you want to create your theme.</li>
              <li>Run the command below to clone a starter theme. Your theme will be created in a new subdirectory.</li>
            </ol>
            <div class="init-cmd"><span class="prompt" style="color:var(--accent)">$</span> commerceforge theme init</div>
          </div>
        </div>
      </div>
      <div class="accordion-item" data-accordion="headless">
        <button class="accordion-trigger" onclick="toggleAccordion('headless')" aria-expanded="false">
          <span class="acc-label"><span class="acc-num">3</span> Headless storefronts</span>
          <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9"/></svg>
        </button>
        <div class="accordion-content">
          <div class="accordion-inner">
            <ol>
              <li>Install CommerceForge CLI globally using the command above.</li>
              <li>Navigate to the directory where you want to create your Hydrogen storefront.</li>
              <li>Run the command below to initialize a Hydrogen storefront in a new subdirectory.</li>
            </ol>
            <div class="init-cmd"><span class="prompt" style="color:var(--accent)">$</span> commerceforge hydrogen init</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Launch CTA -->
<section class="section">
  <h2 class="section-title">Launch and grow</h2>
  <p class="section-subtitle">Reach millions of merchants through CommerceForge's distribution channels.</p>
  <div class="launch-grid">
    <div class="launch-card">
      <h3>App Marketplace</h3>
      <p>When you're ready, submit your app to the CommerceForge App Marketplace so merchants can find and buy your app through search or personalized recommendations.</p>
      <a href="#">See App Marketplace requirements →</a>
    </div>
    <div class="launch-card">
      <h3>Theme Store</h3>
      <p>Promote and sell your custom theme to merchants building their brands on the CommerceForge Theme Store.</p>
      <a href="#">See Theme Store requirements →</a>
    </div>
  </div>
</section>

<!-- Community -->
<section class="section">
  <h2 class="section-title">Community resources</h2>
  <p class="section-subtitle">Connect, learn, and build with the CommerceForge developer community.</p>
  <div class="community-grid">
    <a href="#" class="community-card">
      <h4>Dev Community →</h4>
      <p>Q&A and advice from CommerceForge community experts</p>
    </a>
    <a href="#" class="community-card">
      <h4>Developer Changelog →</h4>
      <p>The latest CommerceForge ecosystem updates</p>
    </a>
    <a href="#" class="community-card">
