function switchTab(tab) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  document.querySelectorAll('.tab-content').forEach(c => c.classList.toggle('active', c.id === 'tab-' + tab));
}

// Accordion toggle - only one open at a time
function toggleAccordion(name) {
  document.querySelectorAll('.accordion-item').forEach(item => {
    const isOpen = item.dataset.accordion === name && !item.classList.contains('open');
    item.classList.toggle('open', isOpen);
    item.querySelector('.accordion-trigger').setAttribute('aria-expanded', isOpen);
  });
}

// Copy install command
function copyInstall(btn) {
  const activeTab = document.querySelector('.tab-content.active code');
  const text = activeTab ? activeTab.textContent.replace(/\$ /g, '').replace(/#.*\n/g, '').trim() : '';
  navigator.clipboard.writeText(text).then(() => {
    btn.textContent = 'Copied!';
    setTimeout(() => btn.textContent = 'Copy', 2000);
  });
}

// Keyboard shortcut for search
document.addEventListener('keydown', e => {
  if (e.key === '/' && !['INPUT','TEXTAREA'].includes(document.activeElement.tagName)) {
